/*
 * Ink Finance service worker.
 *
 * This file is served from the site root, so its scope is the whole origin.
 * It is hand-written rather than generated by a Workbox plugin for one reason
 * that matters here: the caching rules below are the security-relevant part of
 * the PWA, and they are easier to read and to test as ~120 lines of plain code
 * than as build-time configuration.
 *
 * The rules, and why:
 *
 *   /api/*          NEVER intercepted. This is a finance app; a cached balance
 *                   is a wrong balance, and a cached 200 for a write would be
 *                   far worse. Every API call goes straight to the network.
 *                   Note that offline reads therefore fail — that is correct,
 *                   and the app shows an offline banner when it happens.
 *   navigations     Network first, falling back to a cached shell. Network
 *                   first (not cache first) so a deploy is picked up on the
 *                   next launch instead of serving a stale index.html that
 *                   references asset filenames the server no longer has.
 *   /assets/*       Cache first. Vite content-hashes these, so a given URL is
 *                   immutable — the cheapest correct strategy.
 *   everything else Stale-while-revalidate: icons, the manifest, and the
 *                   Google Fonts CSS/woff2 (cross-origin, so opaque responses,
 *                   which is why the check below accepts `type === 'opaque'`
 *                   as well as `ok`).
 *
 * Bumping VERSION is what invalidates everything: `activate` deletes every
 * cache whose name does not start with the new version.
 */

const VERSION = 'ink-finance-v1';

const SHELL_CACHE = `${VERSION}-shell`;
const ASSET_CACHE = `${VERSION}-assets`;
const STATIC_CACHE = `${VERSION}-static`;

/** Kept small on purpose: the shell plus the install chrome, nothing else. */
const PRECACHE = [
  '/',
  '/index.html',
  '/manifest.webmanifest',
  '/icon.svg',
  '/icon-192.png',
  '/icon-512.png',
  '/apple-touch-icon.png',
];

/** Which bucket a request belongs to. Pure, and tested directly. */
function classify(url, mode, origin) {
  let parsed;
  try {
    parsed = new URL(url);
  } catch {
    return 'other';
  }
  if (parsed.origin !== origin) return 'third-party';
  if (parsed.pathname.startsWith('/api/')) return 'api';
  if (parsed.pathname === '/sw.js') return 'sw';
  if (mode === 'navigate') return 'navigation';
  if (parsed.pathname.startsWith('/assets/')) return 'asset';
  return 'static';
}

/** `ok` covers normal responses; opaque ones (cross-origin, no-cors) have status 0. */
function isCacheable(res) {
  return Boolean(res) && (res.ok || res.type === 'opaque');
}

async function precache() {
  const cache = await caches.open(SHELL_CACHE);
  // Added one at a time: `addAll` rejects as a unit, and a single 404 would
  // then leave the app with no service worker at all.
  await Promise.all(
    PRECACHE.map(async (url) => {
      try {
        await cache.add(new Request(url, { cache: 'reload' }));
      } catch {
        /* not fatal — the fetch handler will fill this in on first use */
      }
    }),
  );
}

async function networkFirstShell(request) {
  const cache = await caches.open(SHELL_CACHE);
  try {
    const response = await fetch(request);
    // Always stored under /index.html, whatever path was requested: the static
    // host rewrites every route to index.html, so all routes share one entry.
    if (response && response.ok) await cache.put('/index.html', response.clone());
    return response;
  } catch {
    const cached = (await cache.match('/index.html')) || (await cache.match('/'));
    return cached || Response.error();
  }
}

async function cacheFirst(request, cacheName) {
  const cache = await caches.open(cacheName);
  const hit = await cache.match(request);
  if (hit) return hit;
  const response = await fetch(request);
  if (isCacheable(response)) await cache.put(request, response.clone());
  return response;
}

async function staleWhileRevalidate(request, cacheName, event) {
  const cache = await caches.open(cacheName);
  const hit = await cache.match(request);

  const refresh = fetch(request)
    .then(async (response) => {
      if (isCacheable(response)) await cache.put(request, response.clone());
      return response;
    })
    .catch(() => undefined);

  if (hit) {
    // Keep the worker alive until the refresh lands, then answer from cache.
    event.waitUntil(refresh);
    return hit;
  }

  return (await refresh) || Response.error();
}

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      await precache();
      // Activate immediately instead of waiting for every tab to close. The
      // page reloads itself on `controllerchange` (see src/lib/pwa.ts), which
      // keeps the running bundle and the worker from different deploys.
      await self.skipWaiting();
    })(),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const names = await caches.keys();
      await Promise.all(
        names.filter((name) => !name.startsWith(VERSION)).map((name) => caches.delete(name)),
      );
      await self.clients.claim();
    })(),
  );
});

self.addEventListener('fetch', (event) => {
  const request = event.request;

  // Writes are never cached and never queued: a queued payment that replays
  // later is not something this app should do silently.
  if (request.method !== 'GET') return;

  // Chrome DevTools issues these; intercepting them throws.
  if (request.cache === 'only-if-cached' && request.mode !== 'same-origin') return;

  const kind = classify(request.url, request.mode, self.location.origin);
  if (kind === 'api' || kind === 'sw') return; // straight to the network
  if (kind === 'navigation') {
    event.respondWith(networkFirstShell(request));
    return;
  }
  if (kind === 'asset') {
    event.respondWith(cacheFirst(request, ASSET_CACHE));
    return;
  }
  event.respondWith(staleWhileRevalidate(request, STATIC_CACHE, event));
});

self.addEventListener('message', (event) => {
  const type = event.data && event.data.type;

  if (type === 'ink:version') {
    const reply = { type: 'ink:version', version: VERSION };
    if (event.source) event.source.postMessage(reply);
    else if (event.ports && event.ports[0]) event.ports[0].postMessage(reply);
    return;
  }

  if (type === 'ink:skip-waiting') {
    self.skipWaiting();
  }
});
